<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="shopify-api-key" content="{{ $clientId }}"><title>Deco Marketing Test</title><script src="https://cdn.shopify.com/shopifycloud/app-bridge.js"></script></head><body style="font:16px Arial;background:#f4f6f8;padding:32px;color:#172b3a"><main style="max-width:650px;background:white;padding:32px;border-radius:16px;margin:auto"><h1>营销自动化 · 测试版</h1><p>连接店铺：{{ $shop }}。对账模式仅读取数据和虚拟发送，旧 MACFOX CRM 保持运行。</p><p id="status">点击连接，验证独立应用授权。</p><button id="connect">连接测试应用</button><p><a id="manage" href="{{ url('/marketing') }}" target="_blank" rel="noopener">打开 DecoAdmin 营销后台</a></p></main><script>
const button=document.getElementById('connect');
button.addEventListener('click',async()=>{button.disabled=true;try{const token=await shopify.idToken();const r=await fetch({{ Illuminate\Support\Js::from(url('/api/shopify-app/marketing/bootstrap').'?shop='.$shop) }},{method:'POST',headers:{Authorization:`Bearer ${token}`,Accept:'application/json'}});const data=await r.json();document.getElementById('status').textContent=r.ok?'测试店铺已连接。':(data.message??'连接失败，请重试。');if(r.ok)document.getElementById('manage').href=data.management_url;}catch{document.getElementById('status').textContent='连接未完成，请从 Shopify 后台重新打开。';}finally{button.disabled=false;}});
</script></body></html>
